// CEKIVA reads the type of an image from the file name: name the downloaded file explicitly.
const item = $input.first();
const b = item.binary && item.binary.data;
if (!b) throw new Error('The post image could not be downloaded from Google Drive.');
const mime = String(b.mimeType || '').toLowerCase();
const EXT = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif' };
if (!EXT[mime]) throw new Error('Unsupported image type (' + (mime || 'unknown') + '). CEKIVA takes JPEG, PNG, WebP or GIF up to 8 MB.');
b.fileName = 'image.' + EXT[mime];
return [{ json: {}, binary: { data: b } }];

// CEKIVA publishing: ONE POST /v1/posts to the network the router agent chose (the route of the approved post).
// X/Twitter is not here on purpose: CEKIVA retired that channel.
const CONFIG = {
  CLIENT_ID: '',      // optional: id of one of your CEKIVA client workspaces (GET https://cekiva.com/api/v1/clients); empty = your primary workspace
  PUBLISH_NOW: true,  // true = publish right away; false = publish at SCHEDULED_AT
  SCHEDULED_AT: '',   // ISO 8601 with a time zone, e.g. 2026-12-01T09:00:00Z (used only when PUBLISH_NOW is false)
};
const LIMITS = { instagram: 2200, facebook_page: 63000, linkedin: 3000, threads: 500, bluesky: 300 };
const MAP = { instagram: 'instagram', facebook: 'facebook_page', linkedin: 'linkedin', threads: 'threads', bluesky: 'bluesky' };

const data = ($('Extract as JSON').first().json || {}).data || {};
const route = String(data.route || '').toLowerCase().trim();
if (['xtwitter', 'twitter', 'x'].includes(route)) throw new Error('X/Twitter is not supported: CEKIVA retired that channel.');
const platform = MAP[route];
if (!platform) throw new Error('Unknown route "' + route + '". Use instagram, facebook, linkedin, threads or bluesky.');
const imageUrl = $input.first().json.url;
if (!imageUrl) throw new Error('CEKIVA did not return an image url.');

const content = data.social_content || {};
const fields = content.schema || {};
const common = content.common_schema || {};
const text = (k) => (typeof fields[k] === 'string' ? fields[k].trim() : '');
const parts = ({ instagram: ['caption', 'call_to_action'], facebook_page: ['post', 'call_to_action'], linkedin: ['post', 'call_to_action'], threads: ['text_post', 'call_to_action'], bluesky: ['post'] })[platform].map(text).filter(Boolean);
const tags = (Array.isArray(common.hashtags) ? common.hashtags : []).map((h) => String(h).trim()).filter(Boolean).map((h) => (h.startsWith('#') ? h : '#' + h)).join(' ');
if (!parts.length) throw new Error('The approved post has no text for ' + platform + '. Check the schema Google Doc (field names for ' + route + ').');
let body = parts.join('\n\n');
if (tags && (body + '\n\n' + tags).length <= LIMITS[platform]) body += '\n\n' + tags; // hashtags only where they fit
if (body.length > LIMITS[platform]) body = body.slice(0, LIMITS[platform] - 1).trimEnd() + '…';

const scheduleAt = !CONFIG.PUBLISH_NOW && CONFIG.SCHEDULED_AT ? CONFIG.SCHEDULED_AT : null;
// The body of POST /v1/posts exactly as the CEKIVA API expects it.
const request = { platforms: [platform], content: body, image_url: imageUrl, media_urls: [imageUrl], scheduled_for: scheduleAt || new Date().toISOString(), publish_now: !scheduleAt };
if (CONFIG.CLIENT_ID) request.client_id = CONFIG.CLIENT_ID;
return [{ json: { platform, name: (content.root_schema || {}).name || '', request } }];

// One uniform result row and a short message for Telegram.
const sent = $('Build CEKIVA post').first().json;
const r = $input.first().json;
const body = r.body;
const post = Array.isArray(body) ? body[0] : null;
const err = body && !Array.isArray(body) && body.error && typeof body.error === 'object' ? body.error : null;
const status = Number(r.statusCode) || null;
const ok = status !== null && status >= 200 && status < 300 && !!post;
const row = {
  platform: sent.platform,
  result: ok ? 'Success' : 'Error',
  http_status: status,
  post_id: post ? post.id : null,
  post_status: post ? post.status : null,
  credits_charged: post ? post.credits_charged : null,
  error_code: err ? err.code : (r.error ? 'CEKIVA_UNREACHABLE' : null),
  error_message: err ? err.message : (r.error ? String(r.error.message || r.error).slice(0, 200) : (ok ? null : 'Unexpected response')),
  hint: err ? err.hint : null,
};
row.message = ok ? '✅ ' + row.platform + ': "' + sent.name + '" is ' + row.post_status + ' in CEKIVA.' : '❌ ' + row.platform + ': ' + (row.error_code || '') + ' ' + (row.error_message || '');
return [{ json: row }];
